#!/bin/bash
P=/scratch/jjyeung/orch_n30/so_in/scratch/jjyeung/orch_n30/swarm_opt/work/prompts
for c in so_pack_a_fix4:so_pack_a:FIX4:so_cr_pack_a5:cr_pack_a5.md so_step_fix5:so_step:FIX5:so_cr_step6:cr_step6.md so_read_fix6:so_read:FIX6:so_cr_read7:cr_read7.md so_syncfix:so_syncfix:BUILD:so_cr_syncfix:cr_syncfix.md so_reads228:so_reads228:BUILD:so_cr_reads228:cr_reads228.md so_syncfix_fix1:so_syncfix:FIX1:so_cr_syncfix2:cr_syncfix2.md so_read_fix7:so_read:FIX7:so_cr_read8:cr_read8.md so_reads228_fix1:so_reads228:FIX1:so_cr_reads228_2:cr_reads228_2.md so_syncfix_fix2:so_syncfix:FIX2:so_cr_syncfix3:cr_syncfix3.md so_read_fix8:so_read:FIX8:so_cr_read9:cr_read9.md so_syncfix_fix3:so_syncfix:FIX3:so_cr_syncfix4:cr_syncfix4.md so_reads228_fix2:so_reads228:FIX2:so_cr_reads228_3:cr_reads228_3.md so_read_fix9:so_read:FIX9:so_cr_read10:cr_read10.md; do IFS=: read -r fx ws mk rv pr <<< "$c"
  if [[ -f /scratch/jjyeung/orch_n30/$ws/work/${mk}_STARTED_$fx ]] && ! tmux has-session -t =$fx 2>/dev/null && [[ ! -d /scratch/jjyeung/orch_n30/$rv ]] && [[ -f $P/$pr ]]; then bash $P/cursor_start.sh $rv $P/$pr; fi; done
date -u +%H:%MZ; bash $P/qrun.sh | grep -v "ENDED\|^-- so_"
for c in so_cr_step6 so_cr_read7 so_cr_pack_a5 so_cr_syncfix so_cr_reads228 so_cr_syncfix2 so_cr_read8 so_cr_reads228_2 so_cr_syncfix3 so_cr_read9 so_cr_syncfix4 so_cr_reads228_3 so_cr_read10; do [[ -d /scratch/jjyeung/orch_n30/$c ]] && echo "$c: $(head -1 /scratch/jjyeung/orch_n30/$c/REVIEW_VERDICT.md 2>/dev/null) tmux=$(tmux has-session -t =$c 2>/dev/null && echo y || echo n)"; done
for t in so_read so_pack_a so_step so_syncfix so_reads228; do echo "$t: $(head -1 /scratch/jjyeung/orch_n30/$t/out/REPORT.md 2>/dev/null | cut -c1-160)"; done
uptime; free -g | sed -n 2p
